55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const COMPONENT_TYPES = ["rune", "moonstone"];
68	const BLOCK_SIZE = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	
71	/** Rounds to whole G in the MHPCO's favour. */
72	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
73	
74	const countByType = (items: Item[]): Map<string, number> => {
75	  const counts = new Map<string, number>();
76	  for (const item of items) {
77	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
78	  }
79	  return counts;
80	};
81	
82	/**
83	 * Components are priced per group of alike items, because a building block of
84	 * exactly 3 alike components earns a special rate. Main items price per item.
85	 */
86	const basePremiumForGroup = (type: string, count: number): number => {
87	  if (COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE) {
88	    return BLOCK_BASE_PREMIUM;
89	  }
90	  return count * BASE_PREMIUM_BY_TYPE[type];
91	};
92	
93	const quotePremium = (items: Item[]): number => {
94	  let policyBasePremium = 0;
95	  for (const [type, count] of countByType(items)) {
96	    policyBasePremium += basePremiumForGroup(type, count);
97	  }
98	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
99	  return roundUpToWholeG(policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE);
100	};
101	
102	export const runScenario = (scenario: Scenario): ScenarioResult => {
103	  return {
104	    results: scenario.steps.map((step) => ({
105	      premium: quotePremium((step as QuoteStep).items),
106	    })),
107	  };
108	};
